def add(t=''):lines.append(t.strip()+'\n')
def num(x,d=4):return f'{x:.{d}f}'
def percent(x):return num(x*100,2)
def table(headers,rows):
    add('\n'.join(['| '+' | '.join(map(str,headers))+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x).replace('|','/').replace('\n',' ') for x in r)+' |' for r in rows]))
def change(a,b):return [num(b-a),num((b-a)/a*100,2)+'%' if a else 'N/A (zero baseline)']
def compact(r):return ', '.join(str(v) for v in r)

